        if (player.capabilities.isCreativeMode)
        {
            BlockPos blockpos = pos.offset(state.getValue(FACING).getOpposite());
            Block block = worldIn.getBlockState(blockpos).getBlock();

            if (block == Blocks.PISTON || block == Blocks.STICKY_PISTON)
