    public int getHeight(int x, int z) {
        int i;

        if (x >= -30000000 && z >= -30000000 && x < 30000000 && z < 30000000) {
            if (this.isChunkLoaded(x >> 4, z >> 4, true)) {
                i = this.getChunk(x >> 4, z >> 4).getHeightValue(x & 15, z & 15);
            } else {
                i = 0;
