    {
        int i = (int)(worldTime % 24000L);
        float f = ((float)i + partialTicks) / 24000.0F - 0.25F;

        if (f < 0.0F)
        {
            ++f;
        }

        if (f > 1.0F)
        {
            --f;
        }

        float f1 = 1.0F - (float)((MathHelper.cos((float) (f * Math.PI)) + 1.0D) / 2.0D);
        f = f + (f1 - f) / 3.0F;
        return f;
    }

