        this.dataManager.register(FLAGS, (byte) 0);
        this.dataManager.register(AIR, 300);
        this.dataManager.register(CUSTOM_NAME_VISIBLE, Boolean.FALSE);
        this.dataManager.register(CUSTOM_NAME, "");
