        }

        this.seenCredits = compound.getBoolean("seenCredits");

        if (compound.hasKey("recipeBook", 10))
        {
            this.recipeBook.read(compound.getCompoundTag("recipeBook"));
        }
    }

    public static void registerFixesPlayerMP(DataFixer p_191522_0_)
