                        return false;
                    }
                    else if (this.collarColors == ConnectedParser.DYE_COLORS_INVALID)
                    {
                        Config.warn("Invalid collar colors: " + path);
                        return false;
                    }
                    else
                    {
                        return true;
                    }
                }
            }
        }
        else
        {
            Config.warn("Invalid skins for rule: " + this.index);
            return false;
        }
    }

