            for (int i = 0; i < cp.items.length; ++i)
            {
                int j = cp.items[i];

                if (j <= 0)
                {
                    Config.warn("Invalid item ID: " + j);
                }
                else
                {
                    addToList(cp, itemList, j);
                }
            }
        }
