        } else if (packetIn.getType() == 63) {
            entity = new EntityLargeFireball(this.world, d0, d1, d2, (double) packetIn.getSpeedX() / 8000.0D, (double) packetIn.getSpeedY() / 8000.0D, (double) packetIn.getSpeedZ() / 8000.0D);
