        PacketThreadUtil.checkThreadAndEnqueue(packetIn, this, this.client);
        Container container = null;
        EntityPlayer entityplayer = this.client.player;

        if (packetIn.getWindowId() == 0) {
            container = entityplayer.inventoryContainer;
