            return -1;
        }
        else
        {
            int i = renderEnv.getMetadata();
            CustomColors.IColorizer customcolors$icolorizer;

            if (block != Blocks.GRASS && block != Blocks.TALLGRASS && block != Blocks.DOUBLE_PLANT)
            {
                if (block == Blocks.DOUBLE_PLANT)
