                else if (block == Blocks.LEAVES)
                {
                    switch (i & 3)
                    {
                        case 0:
                            customcolors$icolorizer = COLORIZER_FOLIAGE;
                            break;

                        case 1:
                            customcolors$icolorizer = COLORIZER_FOLIAGE_PINE;
                            break;

                        case 2:
                            customcolors$icolorizer = COLORIZER_FOLIAGE_BIRCH;
                            break;

                        default:
                            customcolors$icolorizer = COLORIZER_FOLIAGE;
                    }
                }
                else if (block == Blocks.LEAVES2)
                {
                    customcolors$icolorizer = COLORIZER_FOLIAGE;
                }
                else
