    private static void addToList(CustomColormap cm, List list, int id)
    {
        while (id >= list.size())
        {
            list.add(null);
        }

        List subList = (List)list.get(id);

        if (subList == null)
        {
            subList = new ArrayList();
            list.set(id, subList);
        }

        subList.add(cm);
    }

